package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;import org.w3c.dom.*;
/** Target/source freshness and isolation, without automatic navigation or document writes. */
final class MapPartChoiceGuardChecks {
 final MapPartConfirmationChecks b;final MapAndroidChecks m;final MapVertexConfirmationChecks c;final GeometryConfirmationChecks g;final ManagerVisualChecks v;final ManagerRotationChecks r;
 MapPartChoiceGuardChecks(MapPartConfirmationChecks b){this.b=b;m=b.m;c=b.c;g=b.g;v=b.v;r=b.r;}
 void open(long id)throws Exception{new MapUndoGuardChecks(new MapUndoRotationChecks(m)).open(id,true);m.dragVertex(1,14,8,false);m.check(g.key().equals("0.1")&&(Integer)m.call(m.vertexState(),"undoCount",new Class[]{})==1,"part guard owns exact nonzero dirty input and Undo");b.prompt();}
 void rotate(int rotation)throws Exception{Activity old=m.activity;c.p.rotate(rotation);m.check(old!=m.activity&&old.isDestroyed(),"part-choice guard actually destroyed/recreated Activity");if(m.editorField("mapCanvas")!=null){c.settledMapLayout();m.check(c.layout().getBoolean("interactiveThreshold"),"part-choice original map80px interaction guard");}}
 void change(Object store,long id,boolean target,boolean remove)throws Exception{Object doc=r.load(store,id);Element f=m.element(doc,"point"),shape=(Element)f.getElementsByTagNameNS("*",target?"Point":"LineString").item(0);if(remove)shape.getParentNode().removeChild(shape);else((Element)shape.getElementsByTagNameNS("*","coordinates").item(0)).setTextContent(target?"9.5,8.5,75":"14,24,34 15,25,35 16,26,36");m.staticCall("ProjectWrites","savePreservingAssets",new Class[]{m.storeClass,long.class,m.codec},store,id,doc);}
 void reject(Object store,String kind)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false);try{Object doc=r.load(store,id);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id);String raw=m.editorText(),token=(String)m.editorField("expected"),process=(String)m.editorField("VERTEX_SESSION"),target=b.targetToken(),stamp=(String)m.staticCall("VertexEditDraft","stamp",new Class[]{String.class},raw);b.identity(id,process,token,stamp,target);
 boolean before=kind.endsWith("before")||kind.equals("missing-target"),targetChanged=kind.startsWith("target")||kind.equals("missing-target");if(before)change(store,id,targetChanged,kind.equals("missing-target"));rotate(UiAutomation.ROTATION_FREEZE_90);b.identity(id,process,token,stamp,target);if(!before){m.check(b.present()&&b.enabled(),"valid restored intent permits only an explicit original switch");if(kind.equals("main-changed")){raw+="\n23.5 13.5 33.5";final String newer=raw;final EditText field=(EditText)m.editorField("input");m.runOnMainSync(()->field.setText(newer));}else change(store,id,targetChanged,false);m.click("Сменить контур");m.geometryReady();}
 byte[] current=r.xml(r.load(store,id));m.check(b.present()&&!b.enabled()&&m.editorText().equals(raw),"stale source/target/newer main cannot discard or navigate original private input");b.identity(id,process,token,stamp,target);g.unchanged(store,id,current,assets);rotate(UiAutomation.ROTATION_FREEZE_0);m.check(b.present()&&!b.enabled()&&m.editorText().equals(raw),"blocked original choice and newer raw survive reverse recreation");b.identity(id,process,token,stamp,target);g.unchanged(store,id,current,assets);b.snapshot(kind);m.click("Продолжить редактирование");m.check(m.editorField("partChoice")==null&&m.editorText().equals(raw),"Cancel clears only rejected intent and preserves current raw");g.unchanged(store,id,current,assets);rotate(UiAutomation.ROTATION_FREEZE_90);m.check(m.editorField("partChoice")==null&&!b.present()&&m.editorText().equals(raw),"rejected/cancelled intent never reopens or navigates after further recreate");g.unchanged(store,id,current,assets);v.emit("MAP_PART_REJECT "+kind+" PASS");
 }finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void foreign(Object store,boolean project)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false),other=-1;try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));long target=id;if(project){Object copy=r.parse(xml);m.assets(copy).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},copy,"QA_PART_CHOICE_FOREIGN");target=other;}open(id);final long pid=target;final String feature=project?"point":"other";m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",pid).putExtra("feature",feature)));
 for(int direction:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){rotate(direction);m.check((Long)m.editorField("project")==target&&feature.equals(m.editorField("featureId"))&&m.editorField("partChoice")==null&&!b.present()&&m.editorField("mapCanvas")==null&&m.editorField("mapState")==null&&m.editorText().equals(project?"8 9 7":"22 12 32"),"foreign sameXML project/feature never adopts old choice/raw/map/Undo");g.unchanged(store,id,xml,assets);g.unchanged(store,target,xml,assets);}b.snapshot(project?"foreign-project":"foreign-feature");v.emit("MAP_PART_FOREIGN project="+project+" PASS");
 }finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}
 void cancel(Object store)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id);String raw=m.editorText();m.click("Продолжить редактирование");for(int direction:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){rotate(direction);m.check(m.editorField("partChoice")==null&&!b.present()&&m.editorText().equals(raw)&&g.key().equals("0.1")&&(Integer)m.call(m.vertexState(),"selected",new Class[]{})==1&&(Integer)m.call(m.vertexState(),"undoCount",new Class[]{})==1,"Cancel consumes choice once while retaining original raw/key/selection/Undo across recreations");g.unchanged(store,id,xml,assets);}b.snapshot("cancel-ghost");v.emit("MAP_PART_CANCEL_GHOST PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void save(Object store)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id);rotate(UiAutomation.ROTATION_FREEZE_90);m.check(b.present()&&b.enabled(),"same intent allows explicit target confirmation");m.click("Сменить контур");m.geometryReady();m.mapEditorReady();m.check(g.key().equals("0.0")&&m.editorText().equals("8 9 7")&&m.editorField("partChoice")==null,"explicit Confirm selects exact Point and consumes intent");g.unchanged(store,id,xml,assets);rotate(UiAutomation.ROTATION_FREEZE_0);m.check(!b.present()&&m.editorField("partChoice")==null&&g.key().equals("0.0")&&!(Boolean)m.call(m.vertexState(),"canUndo",new Class[]{}),"confirmed target never replays source intent/history on later recreate");g.unchanged(store,id,xml,assets);m.click("Координаты списком");m.inputs("8.25 9.25 70");g.unchanged(store,id,xml,assets);m.click("Сохранить");m.geometryReady();Object expected=r.parse(xml),actual=r.load(store,id);Element point=(Element)m.element(expected,"point").getElementsByTagNameNS("*","Point").item(0);((Element)point.getElementsByTagNameNS("*","coordinates").item(0)).setTextContent("9.25,8.25,70.0");m.check(m.treeToken(expected).equals(m.treeToken(actual)),"separate explicit Save changes only target Point, preserving original source LineString and every other DOM node");r.sameAssets(actual,assets);b.snapshot("target-saved");v.emit("MAP_PART_TARGET_SAVE PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void run()throws Exception{int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());try{for(String kind:new String[]{"source-before","source-after","target-before","target-after","main-changed","missing-target"})reject(store,kind);foreign(store,true);foreign(store,false);cancel(store);save(store);m.check(m.requests.get()==requests,"all guarded part choices stay local");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);m.call(store,"close",new Class[]{});}}
}
